mapper.select:
SELECT A.TST_UNQ_KY_VAL, A.FRM_UNQ_KY_VAL, A.CHCK_STRT_DT, A.CHCK_END_DT, REGEXP_REPLACE(CHCK_STRT_DT, '(.{4})(.{2})(.{2})','\1-\2-\3') || ' ~ ' || REGEXP_REPLACE(CHCK_END_DT, '(.{4})(.{2})(.{2})','\1-\2-\3') AS CHCK_DT, C.PRCDOC_UNQ_KY_VAL, C.PRCDOC_NO, C.PRCDOC_NM, C.DOC_TYP, C.DOC_PART_NO, C.PRCDOC_RVSN_NO, C.PRCDOC_CFY, CASE WHEN C.PRCDOC_CFY = 'P' THEN '정주기' WHEN C.PRCDOC_CFY = 'M' THEN '점검지' ELSE '' END AS PRCDOC_CFY_NM, C.ATCT_NM, C.MNTRG_YN, B.ATCT_CFY, A.TITL_NM, A.CHKPR_ID, A.CHKPR_FNM, A.CNMR_ID, A.CNMR_FNM, A.ATWT_ID, A.ATWT_FNM, A.WRKOR_NO, A.ATWT_PPL_CNT, A.ATWT_RQST_YN, A.PRSTS_CFY, CASE WHEN A.PRSTS_CFY = 'R' THEN '준비' WHEN A.PRSTS_CFY = 'A' THEN '허가' WHEN A.PRSTS_CFY = 'F' THEN '수행' WHEN A.PRSTS_CFY = 'S' THEN '정지' WHEN A.PRSTS_CFY = 'C' THEN '완료' ELSE '' END AS PRSTS_CFY_NM, A.REGPR_ID, A.REGPR_NM, A.RG_DT, TO_CHAR(A.RG_DT, 'YYYY-MM-DD') AS FM_RG_DT, (SELECT T2.ATFL_GRUP_NM || '/' || T2.ATFL_PHCL_NM || '.' || T2.ATFL_FEXT_NM FROM GE_MP_JOB_S T1, GE_MP_FILE_S T2 WHERE T1.UNQ_KY_VAL = T2.UNQ_NO AND T2.ATFL_GRUP_NM ='GE_MP_JOB_S' AND T1.TST_UNQ_KY_VAL = A.TST_UNQ_KY_VAL AND T2.ATFL_ID = '1') JOB_FNAME1, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_CHECK_S' AND UNQ_NO = A.TST_UNQ_KY_VAL AND ATFL_ID = '1') OZD_FNAME1, (SELECT ATFL_GRUP_NM || '/' || ATFL_PHCL_NM || '.' || ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_DISSAT_S' AND UNQ_NO = A.TST_UNQ_KY_VAL AND ATFL_ID = '1') DIS_FNAME1, (SELECT UNQ_KY_VAL FROM GE_MP_DISSAT_S WHERE TST_UNQ_KY_VAL = A.TST_UNQ_KY_VAL) UNQ_KY_VAL FROM GE_MP_CHECK_S A JOIN GE_MP_FRM_M B ON A.FRM_UNQ_KY_VAL = B.FRM_UNQ_KY_VAL JOIN GE_MP_PRCDOC_M C ON B.PRCDOC_UNQ_KY_VAL = C.PRCDOC_UNQ_KY_VAL
AND C.PRCDOC_CFY = #{PRCDOC_CFY}
AND C.PRCDOC_NO LIKE '%'||#{PRCDOC_NO}||'%'
AND C.PRCDOC_NM LIKE '%'||#{PRCDOC_NM}||'%'
JOIN GE_MP_DISSAT_S D ON A.TST_UNQ_KY_VAL = D.TST_UNQ_KY_VAL WHERE A.DLT_YN = 'N'
AND A.CHCK_STRT_DT >= #{CHCK_STRT_DT}
AND A.CHCK_END_DT <= #{CHCK_END_DT}
AND A.PRSTS_CFY = #{PRSTS_CFY}
AND A.TITL_NM LIKE '%'||#{TITL_NM}||'%'
ORDER BY A.RG_DT DESC

SELECT COUNT(*) FROM GE_MP_CHECK_S A JOIN GE_MP_FRM_M B ON A.FRM_UNQ_KY_VAL = B.FRM_UNQ_KY_VAL JOIN GE_MP_PRCDOC_M C ON B.PRCDOC_UNQ_KY_VAL = C.PRCDOC_UNQ_KY_VAL
AND C.PRCDOC_CFY = #{PRCDOC_CFY}
AND C.PRCDOC_NO LIKE '%'||#{PRCDOC_NO}||'%'
AND C.PRCDOC_NM LIKE '%'||#{PRCDOC_NM}||'%'
JOIN GE_MP_DISSAT_S D ON A.TST_UNQ_KY_VAL = D.TST_UNQ_KY_VAL WHERE A.DLT_YN = 'N'
AND A.CHCK_STRT_DT >= #{CHCK_STRT_DT}
AND A.CHCK_END_DT <= #{CHCK_END_DT}
AND A.PRSTS_CFY = #{PRSTS_CFY}
AND A.TITL_NM LIKE '%'||#{TITL_NM}||'%'
